insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c27-grammar','c2-expert-mediation','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Согласовываем сложные позиции для аудиторий с разным опытом и интересами',14,'🤝','Экспертная медиация','[["Точность для разных аудиторий","Медиация не упрощает смысл до лозунга. Она раскрывает термин, сохраняет ограничения и подбирает примеры, понятные конкретной стороне, явно отделяя перевод позиции от собственной оценки."],["От позиции к интересу","Фиксируй области согласия и разногласия, проверяй перефразирование у сторон и ищи варианты по интересам. Медиатор организует понимание, но не присваивает себе право решения."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',323,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
