insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Составьте: Если обе стороны одинаково понимают риск, можно обсуждать допустимый предел.','["Jeżeli obie strony tak samo rozumieją ryzyko, można omówić dopuszczalny próg.","Ryzyko strony rozumieją, więc próg znika.","Dopuszczalny próg rozumie obie strony."]',0,'Условие jeżeli отделяет согласование понятия от следующего решения.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Составьте: Иными словами, учёные требуют проверки, а жители — понятного срока.','["Innymi słowy, naukowcy oczekują weryfikacji, mieszkańcy zaś jasnego terminu.","Naukowcy mieszkańcy termin weryfikują inaczej słowy.","Mieszkańcy nie mają żadnych oczekiwań."]',0,'Innymi słowy вводит проверяемую переформулировку, zaś сопоставляет интересы.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Która parafraza zachowuje warunek brzegowy?','["Rozwiązanie działa przy małym obciążeniu; przy większym wymaga ponownego testu.","Rozwiązanie działa zawsze.","Rozwiązanie nigdy nie działa."]',0,'Первая версия сохраняет область применимости экспертного вывода.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Jak sprawdzić trafność mediacji?','["Poprosić każdą stronę o potwierdzenie parafrazy.","Uznać własne streszczenie za ostateczne.","Usunąć punkty sporne."]',0,'Подтверждение сторон снижает риск смысловой подмены.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Co neutralizuje napięcie bez zamiatania sporu?','["Nazwanie wspólnego celu i dokładnego punktu rozbieżności.","Stwierdzenie, że konfliktu nie ma.","Przerwanie rozmowy bez podsumowania."]',0,'Общая цель не отменяет точно названного разногласия.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-grammar','Która propozycja nie rozstrzyga za strony?','["Mogę przedstawić dwa warianty i ich konsekwencje; wybór należy do państwa.","Zdecydowałam, który wariant musicie przyjąć.","Nie podam żadnych informacji."]',0,'Медиатор структурирует выбор, сохраняя мандат сторон.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-quiz','Co znaczy „mediatorka”?','["медиатор","общий знаменатель","расхождение позиций"]',0,'„mediatorka” oznacza: медиатор.',0,true);
