insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Dlaczego słowo «bezpieczeństwo» nie wystarczało?','["Strony nadawały mu różny zakres","Było błędne językowo","Informatycy go nie znali"]',0,'Общий термин скрывал разные критерии.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Jak wyjaśniono czułość modelu?','["Przez liczbę możliwie przeoczonych chorych","Przez koszt serwera","Przez długość formularza"]',0,'Термин перевели в практическое последствие.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Jaki warunek brzegowy wskazali informatycy?','["Pilotaż obejmował jedną poradnię","System nie wysyłał komunikatów","Nie zebrano żadnych danych"]',0,'Ограничение касалось переносимости результатов.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Co było wspólnym mianownikiem?','["Wykrywanie przypadków bez przeciążania pacjentów","Natychmiastowe wdrożenie","Rezygnacja z modelu"]',0,'Так была сформулирована общая цель.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Co zapisano przy wariantach?','["Korzyści, ryzyka i potrzebne dane","Tylko koszty","Nazwiska zwolenników"]',0,'Каждый вариант получил прозрачную карту последствий.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c27-reading-check','Jaki był rezultat mediacji?','["Wspólny język i mapa decyzji","Ostateczny wybór systemu","Usunięcie rozbieżności"]',0,'Решение не принято, но условия осмысленного выбора созданы.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c27-tekst','c2-expert-mediation','Экспертная медиация','Согласовываем сложные позиции для аудиторий с разным опытом и интересами','C2',16,'🤝','["W szpitalu spotkali się lekarze, informatycy i przedstawicielki pacjentów, aby omówić system przypominający o badaniach. Lekarze mówili o czułości modelu, pacjenci o liczbie fałszywych alarmów, a informatycy o progu klasyfikacji. Wszyscy używali słowa „bezpieczeństwo”, lecz nadawali mu inny zakres.","Mediatorka zaczęła od uzgodnienia definicji. Poprosiła lekarzy, by przełożyli czułość na praktyczny przykład: ilu chorych system może przeoczyć. Następnie wyjaśniła, że niższy próg zmniejsza to ryzyko, ale zwiększa liczbę powiadomień kierowanych do zdrowych osób.","Przedstawicielka pacjentów potwierdziła parafrazę, lecz dodała, że częste alarmy mogą osłabić zaufanie. Informatycy wskazali warunek brzegowy: wyniki pilotażu dotyczą jednej poradni i nie powinny być automatycznie przenoszone na cały region. Mediatorka zapisała oba ograniczenia bez ich wartościowania.","Wspólnym mianownikiem okazało się wykrycie możliwie wielu przypadków bez przeciążania pacjentów. Powstały dwa warianty: ostrożny pilotaż z częstą kontrolą oraz szersze wdrożenie z możliwością wyłączenia części komunikatów. Przy każdym zapisano korzyści, ryzyka i dane potrzebne do oceny.","Spotkanie nie zakończyło się wyborem. Strony uzgodniły jednak język, kryteria i termin dostarczenia nowych danych. Mediatorka nie rozstrzygnęła za ekspertów ani pacjentów; przekształciła asymetrię wiedzy w wspólną mapę decyzji, na której różnice stały się zrozumiałe i możliwe do negocjowania."]','{"mediatorka":{"lemma":"mediatorka","translation":"медиатор","part_of_speech":"rzeczownik"},"wspólny mianownik":{"lemma":"wspólny mianownik","translation":"общий знаменатель","part_of_speech":"wyrażenie rzeczownikowe"},"rozbieżność stanowisk":{"lemma":"rozbieżność stanowisk","translation":"расхождение позиций","part_of_speech":"wyrażenie rzeczownikowe"},"interes strony":{"lemma":"interes strony","translation":"интерес стороны","part_of_speech":"wyrażenie rzeczownikowe"},"pole porozumienia":{"lemma":"pole porozumienia","translation":"пространство для согласия","part_of_speech":"wyrażenie rzeczownikowe"},"termin specjalistyczny":{"lemma":"termin specjalistyczny","translation":"специальный термин","part_of_speech":"wyrażenie rzeczownikowe"},"asymetria wiedzy":{"lemma":"asymetria wiedzy","translation":"асимметрия знаний","part_of_speech":"wyrażenie rzeczownikowe"},"warunek brzegowy":{"lemma":"warunek brzegowy","translation":"граничное условие","part_of_speech":"wyrażenie rzeczownikowe"},"uzgodnić definicję":{"lemma":"uzgodnić definicję","translation":"согласовать определение","part_of_speech":"wyrażenie czasownikowe"},"przełożyć na język praktyki":{"lemma":"przełożyć na język praktyki","translation":"перевести на язык практики","part_of_speech":"wyrażenie czasownikowe"},"zneutralizować napięcie":{"lemma":"zneutralizować napięcie","translation":"снять напряжение","part_of_speech":"wyrażenie czasownikowe"},"zachować precyzję":{"lemma":"zachować precyzję","translation":"сохранить точность","part_of_speech":"wyrażenie czasownikowe"},"wydobyć potrzebę":{"lemma":"wydobyć potrzebę","translation":"выявить потребность","part_of_speech":"wyrażenie czasownikowe"},"sformułować wariant pośredni":{"lemma":"sformułować wariant pośredni","translation":"сформулировать промежуточный вариант","part_of_speech":"wyrażenie czasownikowe"},"nie rozstrzygać za strony":{"lemma":"nie rozstrzygać za strony","translation":"не решать за стороны","part_of_speech":"fraza"},"mandat negocjacyjny":{"lemma":"mandat negocjacyjny","translation":"переговорный мандат","part_of_speech":"wyrażenie rzeczownikowe"},"język korzyści":{"lemma":"język korzyści","translation":"язык пользы","part_of_speech":"wyrażenie rzeczownikowe"},"protokół rozbieżności":{"lemma":"protokół rozbieżności","translation":"протокол разногласий","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c27-reading-check"}',63,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
