insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c28-grammar','c2-research-synthesis','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Строим осторожный вывод по нескольким неоднородным источникам',14,'🔬','Исследовательский синтез','[["Не среднее арифметическое","Синтез учитывает дизайн, выборку и качество каждого источника. Совпадение результатов усиливает вывод лишь тогда, когда одинаковая ошибка или зависимость источников не объясняет это совпадение."],["Калиброванный вывод","Разделяй наблюдение, интерпретацию и рекомендацию. Называй степень уверенности, альтернативные объяснения и область применимости, не превращая отсутствие доказательства в доказательство отсутствия."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',328,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
