insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Составьте: Результаты совпадают, однако исследования опираются на сходные малые выборки.','["Wyniki są zbieżne, jednak badania opierają się na podobnych małych próbach.","Wyniki są pewne, ponieważ próby nie mają znaczenia.","Podobne wyniki prób badania jednak."]',0,'Jednak вводит методологическое ограничение для внешне согласованных результатов.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Составьте: Чем слабее контроль переменных, тем осторожнее должен быть причинный вывод.','["Im słabsza kontrola zmiennych, tym ostrożniejszy powinien być wniosek przyczynowy.","Kontrola jest słaba, więc przyczyna jest pewna.","Tym zmienna, im przyczynowy wniosek."]',0,'Im..., tym... калибрует силу вывода по качеству контроля.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Który wniosek odróżnia korelację od przyczynowości?','["Związek jest powtarzalny, ale dane obserwacyjne nie rozstrzygają o przyczynie.","Korelacja zawsze dowodzi przyczyny.","Skoro istnieje związek, znamy mechanizm."]',0,'Первая версия признаёт наблюдение и ограничивает причинную интерпретацию.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Jak ważyć sprzeczne źródła?','["Porównać próby, metody, pomiar i ryzyko błędu.","Policzyć publikacje bez oceny jakości.","Wybrać najnowszy tytuł."]',0,'Вес доказательства зависит от метода, а не только от количества источников.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Co oznacza umiarkowany stopień pewności?','["Dane wspierają wniosek, lecz istotne alternatywy pozostają otwarte.","Nie wiadomo absolutnie nic.","Wniosek jest niepodważalny."]',0,'Средняя уверенность сочетает поддержку и реальные ограничения.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-grammar','Gdzie wskazano lukę badawczą?','["Brakuje badań długoterminowych w grupie osób starszych.","Badanie ma trzy tabele.","Autorzy cytują literaturę."]',0,'Фраза точно называет отсутствующий тип данных и популяцию.',5,true);
