insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Co wykazało pierwsze badanie?','["Niewielką poprawę w teście uwagi","Brak jakichkolwiek zmian","Spadek produktywności"]',0,'Эксперимент дал небольшой эффект в тесте внимания.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Dlaczego duża próba nie rozstrzygała przyczynowości?','["Uczestnicy sami wybierali spacery i mogli różnić się innymi cechami","Badanie trwało zbyt długo","Nie pytano o produktywność"]',0,'Самоотбор оставлял смешивающие переменные.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Jaki mechanizm zasugerowały wywiady?','["Przerwę poznawczą od komunikatorów","Wyłącznie zmianę pogody","Rywalizację między pracownikami"]',0,'Качественные данные расширили возможное объяснение.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Jaki wniosek uznano za umiarkowanie pewny?','["Krótkie przerwy sprzyjają subiektywnej koncentracji","Spacer leczy wszystkie problemy","Każdy rodzaj przerwy działa identycznie"]',0,'Итог был ограничен субъективной концентрацией.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Dlaczego rekomendacja miała formę testu?','["Korzyść była prawdopodobna, a ryzyko małe, lecz dowód ograniczony","Nie istniały żadne dane","Spacer był obowiązkowy"]',0,'Рекомендация соразмерна качеству доказательства.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c28-reading-check','Jaką lukę badawczą wskazano?','["Porównanie rodzajów przerw i skutków długoterminowych","Brak definicji pracy","Brak danych o cenie obuwia"]',0,'Финал точно называет недостающие сравнения.',5,true);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c28-tekst','c2-research-synthesis','Исследовательский синтез','Строим осторожный вывод по нескольким неоднородным источникам','C2',16,'🔬','["Zespół analizował, czy krótkie spacery podczas pracy zdalnej poprawiają koncentrację. Pierwsze badanie eksperymentalne obejmowało czterdzieści osób i wykazało niewielką poprawę w teście uwagi. Drugie, obserwacyjne, śledziło tysiąc pracowników i znalazło podobny związek między przerwami a samooceną produktywności.","Pozorna zbieżność nie oznaczała jednak, że dowody są równoważne. Eksperyment lepiej kontrolował porę dnia, lecz trwał tylko tydzień. Badanie obserwacyjne miało większą próbę, ale osoby wybierające spacery mogły różnić się snem, obciążeniem pracą i motywacją.","Wywiady jakościowe dodały trzeci wymiar. Uczestnicy opisywali nie tylko ruch, lecz także chwilowe odcięcie od komunikatorów. Sugerowało to alternatywny mechanizm: korzyść mogła wynikać z przerwy poznawczej, a nie wyłącznie z aktywności fizycznej.","Badacze zważyli źródła zamiast liczyć je jak głosy. Uznali z umiarkowaną pewnością, że regularne krótkie przerwy sprzyjają subiektywnej koncentracji. Nie przesądzili, czy spacer jest lepszy od spokojnego odpoczynku ani czy efekt utrzymuje się przez wiele miesięcy.","Rekomendacja miała więc formę niskiego ryzyka: pracownicy mogą testować krótkie przerwy i obserwować własny rytm, a organizacje nie powinny przedstawiać spaceru jako obowiązkowej terapii wydajności. Luka badawcza dotyczyła porównania rodzajów przerw oraz długoterminowych skutków w różnych zawodach."]','{"synteza źródeł":{"lemma":"synteza źródeł","translation":"синтез источников","part_of_speech":"wyrażenie rzeczownikowe"},"triangulacja danych":{"lemma":"triangulacja danych","translation":"триангуляция данных","part_of_speech":"wyrażenie rzeczownikowe"},"jakość dowodu":{"lemma":"jakość dowodu","translation":"качество доказательства","part_of_speech":"wyrażenie rzeczownikowe"},"próba badawcza":{"lemma":"próba badawcza","translation":"исследовательская выборка","part_of_speech":"wyrażenie rzeczownikowe"},"zmienna zakłócająca":{"lemma":"zmienna zakłócająca","translation":"смешивающая переменная","part_of_speech":"wyrażenie rzeczownikowe"},"ograniczenie metodologiczne":{"lemma":"ograniczenie metodologiczne","translation":"методологическое ограничение","part_of_speech":"wyrażenie rzeczownikowe"},"stopień pewności":{"lemma":"stopień pewności","translation":"степень уверенности","part_of_speech":"wyrażenie rzeczownikowe"},"zbieżność wyników":{"lemma":"zbieżność wyników","translation":"сходимость результатов","part_of_speech":"wyrażenie rzeczownikowe"},"ważyć dowody":{"lemma":"ważyć dowody","translation":"взвешивать доказательства","part_of_speech":"wyrażenie czasownikowe"},"porównać metodologie":{"lemma":"porównać metodologie","translation":"сравнить методологии","part_of_speech":"wyrażenie czasownikowe"},"wyjaśnić rozbieżność":{"lemma":"wyjaśnić rozbieżność","translation":"объяснить расхождение","part_of_speech":"wyrażenie czasownikowe"},"kontrolować zmienną":{"lemma":"kontrolować zmienną","translation":"контролировать переменную","part_of_speech":"wyrażenie czasownikowe"},"zastrzec zakres wniosku":{"lemma":"zastrzec zakres wniosku","translation":"оговорить область вывода","part_of_speech":"wyrażenie czasownikowe"},"wskazać lukę badawczą":{"lemma":"wskazać lukę badawczą","translation":"указать исследовательский пробел","part_of_speech":"wyrażenie czasownikowe"},"nie mylić korelacji z przyczynowością":{"lemma":"nie mylić korelacji z przyczynowością","translation":"не путать корреляцию с причинностью","part_of_speech":"fraza"},"przegląd systematyczny":{"lemma":"przegląd systematyczny","translation":"систематический обзор","part_of_speech":"wyrażenie rzeczownikowe"},"dane jakościowe":{"lemma":"dane jakościowe","translation":"качественные данные","part_of_speech":"wyrażenie rzeczownikowe"},"replikowalność":{"lemma":"replikowalność","translation":"воспроизводимость","part_of_speech":"rzeczownik"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c28-reading-check"}',64,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
